compile.workshop:
variables {
    global:
        0: g
        1: h
}

//Optimize for size enabled
rule ("x") {
    event {
        Ongoing - Global;
    }
    actions {
        If(Compare(Global.g, ==, 1));
            Set Global Variable(g, 2);
            If(Or(Compare(Global.h, ==, Null), Compare(Global.h, ==, Null)));
                Set Global Variable(h, 3);
            End;
        Else;
            If(Or(Compare(Global.h, ==, Null), Compare(Global.h, ==, Null)));
                Set Global Variable(h, 4);
            End;
        End;
        Set Global Variable(g, 5);
    }
}

